        html: `<p>정답이에요. 침전지 표면부하율 계산을 정리할게요.</p>
<p><strong>정의</strong>: 표면부하율(surface loading rate, SLR) = Q/A = 수심/체류시간. 단위는 m³/(m²·d) 또는 m/d.</p>
<p><strong>공식 유도</strong>: 침전지 부피 V = A·H = Q·t. 따라서 H/t = Q/A. 침전지 설계에서 표면부하율은 입자 침강 속도를 결정해요.</p>
<p><strong>대입</strong>: H = 4 m, t = 1 h = 1/24 d. SLR = 4/(1/24) = 96 m³/(m²·d). 정답은 3번이에요.</p>
<p>침전지에서는 표면부하율이 작을수록 작은 입자도 침강할 수 있어 처리 효율이 좋아요. 보통 25~40 m³/(m²·d)로 설계해요. 96은 비교적 큰 값이라 빠른 처리용 침전지에 해당해요.</p>`,
